import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
		int t=Integer.parseInt(br.readLine().trim());
		while(t-->0)
		{
		    int n=Integer.parseInt(br.readLine().trim());
		    int m=3*n;
		    long a[]=new long[m];
		    StringTokenizer st=new StringTokenizer(br.readLine());
		    for(int i=0;i<m;i++)
		    {
		        a[i]=Long.parseLong(st.nextToken());
		    }
		    Arrays.sort(a);
		    long[]p=new long[m+1];
		    for(int i=0;i<m;i++)
		    {
		        p[i+1]=p[i]+a[m-1-i];
		    }
		    long res=0;
		    for(int j=0;j<=n;j++)
		    {
		        int l=0;
		        int h=n-j;
		        while(l<h)
		        {
		            int b=(l+h)/2;
		            long curr=value(j,b,n,p);
		            long next=value(j,b+1,n,p);
		            if(next>=curr){
		                l=b+1;
		            }
		            else{
		                h=b;
		            }
		            
		        }
		        res=Math.max(res,value(j,l,n,p));
		    }
		    System.out.println(res);
		}

	}
	static long value(int A,int B,int N,long []P)
	{
	    int p1=A;
	    int p2=A+2*B;
	    int p3=3*N-2*A-B;
	    return 2*P[p1]+P[p2]+3*P[p3];
	}
}
